# Chandra, Flame's Fury (M20)
# [+1]: Chandra deals 2 damage to any target.                               (compiled[0])
# [-2]: Chandra deals 4 damage to target creature and 2 damage to that creature's controller.
# [-8]: Chandra deals 10 damage to target player and each creature that player controls.

# "that creature's controller" / "that player": an anaphoric read of the ability's one target
# (CONTROLLER_IS with a referent='target' Selector, the Chandra's Incinerator shape), never a
# second target slot.
_the_target = Selector(
    count=QConst(value=1),
    mode=SelectorMode.CHOOSE,
    filter=FAnd(children=()),
    zones=(Zone(kind=ZoneKind.ANY, controller=ControllerRef.ANY),),
    referent='target',
)

minus_two = ActivatedAbility(
    cost=Cost(parts=(CostLoyalty(delta=-2),)),
    effect=Seq(
        steps=(
            A(Verb.DEAL_DAMAGE, {
                'amount': QConst(value=4),
                'target': Selector(
                    count=QConst(value=1),
                    mode=SelectorMode.TARGET,
                    filter=FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                    zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                ),
            }),
            A(Verb.DEAL_DAMAGE, {
                'amount': QConst(value=2),
                'target': Selector(
                    count=QUnbounded(),
                    mode=SelectorMode.ALL,
                    filter=FAtom(pred=FAtomPred.CONTROLLER_IS, who=_the_target),
                    zones=(Zone(kind=ZoneKind.PLAYER, controller=ControllerRef.ANY),),
                ),
            }),
        ),
    ),
)

minus_eight = ActivatedAbility(
    cost=Cost(parts=(CostLoyalty(delta=-8),)),
    effect=Seq(
        steps=(
            A(Verb.DEAL_DAMAGE, {
                'amount': QConst(value=10),
                'target': Selector(
                    count=QConst(value=1),
                    mode=SelectorMode.TARGET,
                    filter=FNot(inner=FAtom(pred=FAtomPred.IS_PERMANENT)),
                    zones=(Zone(kind=ZoneKind.PLAYER, controller=ControllerRef.ANY),),
                ),
            }),
            A(Verb.DEAL_DAMAGE, {
                'amount': QConst(value=10),
                'target': Selector(
                    count=QUnbounded(),
                    mode=SelectorMode.ALL,
                    filter=FAnd(
                        children=(
                            FAtom(pred=FAtomPred.CONTROLLER_IS, who=_the_target),
                            FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                        ),
                    ),
                    zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
                ),
            }),
        ),
    ),
)

abilities = [compiled[0], minus_two, minus_eight, compiled[1]]
